-- PE syndicate map v9.5 and coverage register v9.5: test load. Unreviewed. Not decision-grade.
-- An unreviewed month is never zero deals. Safe to re-run.

create table if not exists gsi_pe_map_test (linked_master_id text, month text, gulf_investor text, investing_entity text, target text, private_equity_counterparty text, pe_role text, gulf_entry_route text, process_stage text, equity_interest_or_position text, investor_specific_amount_millions text, currency text, amount_scope text, source_of_link text, corroboration text, relationship_repeat_evidence text, governance_status text, next_verification text, source_version text default 'v9.5', loaded_id bigint generated always as identity primary key);
alter table gsi_pe_map_test enable row level security;
drop policy if exists "read test rows" on gsi_pe_map_test;
create policy "read test rows" on gsi_pe_map_test for select using (true);
-- re-run guard: clear this test table before reload
truncate table gsi_pe_map_test restart identity;

create table if not exists gsi_coverage_register_test (month text, source_group text, coverage_status text, verified_sources text, open_work text, review_date text, source_version text default 'v9.5', loaded_id bigint generated always as identity primary key);
alter table gsi_coverage_register_test enable row level security;
drop policy if exists "read test rows" on gsi_coverage_register_test;
create policy "read test rows" on gsi_coverage_register_test for select using (true);
-- re-run guard: clear this test table before reload
truncate table gsi_coverage_register_test restart identity;
